const STRIP_LEN = 30;

const STRIP_SYMBOL_NAMES = ['symbol_h1', 'symbol_h2', 'symbol_h3', 'symbol_h4', 'symbol_l1', 'symbol_l2', 'symbol_l3', 'symbol_l4', 'symbol_l5', 'symbol_m1_1', 'symbol_m2_1', 'symbol_scatter'];

function makeIconMatrix(columns: number): string[][] {
    const matrix: string[][] = [];
    for (let i = 0; i < columns; i++) {
        const strip: string[] = [];
        for (let j = 0; j < STRIP_LEN; j++) {
            strip.push(STRIP_SYMBOL_NAMES[(i * 7 + j * 3) % STRIP_SYMBOL_NAMES.length]);
        }
        matrix.push(strip);
    }
    return matrix;
}

/**
 * @param buyMultiple 買入倍率；玩家端 API 由 entry 的 `buy_options` 提供，沒帶時沿用舊協定的 `buy_feature_cost_mul`
 */
export function toLegacySlotConfigData(info: SlotApiGameInfoResponse | null, layout: SlotGridLayout, buyMultiple?: number): any {
    const buyFeatureCostMultiplier = buyMultiple ?? info?.buy_feature_cost_mul ?? 0;
    const columns = layout.columns;
    return {
        base: {
            column: columns,
            shape: [],
            icon_matrix: makeIconMatrix(columns),
        },
        client_config: {
            buy_super_multiplier: buyFeatureCostMultiplier,
            buy_feature_multiplier: buyFeatureCostMultiplier,
            buy_triple_multiplier: buyFeatureCostMultiplier,
        },
        slot_game_info: info,
    };
}

export function toLegacySlotInitData(info: SlotApiGameInfoResponse | null, state: SlotApiGameStateResponse, layout: SlotGridLayout): any {
    const slotState = state.slot_state;
    const columns = layout.columns;
    const betLevel = (slotState?.bet_levels ?? info?.bet_levels ?? []).map(Number);
    const lastBet = slotState?.last_spin?.bet_amount ?? slotState?.default_bet ?? info?.default_bet ?? betLevel[0] ?? 0;
    return {
        machine_info: {
            extra: {},
            bet_level: betLevel,
            last_bet: lastBet,
            icon_indexes: Array.from({ length: columns }, () => 2 + Math.floor(Math.random() * 20)),
            icon_table: [],
            spin_total_win: '0',
        },
        game: {
            balance: state.balance,
            auth_key: 'slot-websocket',
            currency: state.currency,
        },
    };
}

// ===== 玩家端 API v5.1：entry 轉成現有 UI 吃的形狀 =====

/** 下注清單的一個選項：總注額與它對應的 bet_size／bet_level */
export interface SlotBetOption {
    /** 基本注（bet_size × bet_level × base_bet），補到幣別小數位 */
    amount: string;
    size: string;
    level: number;
}

/** 十進位字串拆成「整數 × 10^-scale」，避免浮點誤差 */
function parseDecimal(value: string): { int: number; scale: number } {
    const [whole, fraction = ''] = value.split('.');
    return { int: Number(whole + fraction), scale: fraction.length };
}

/** 整數與小數位數轉回十進位字串：去掉多餘的尾端 0，但至少保留 minScale 位，負數帶負號 */
function formatScaled(value: number, scale: number, minScale: number): string {
    const digits = String(Math.abs(value)).padStart(scale + 1, '0');
    const fraction = digits.slice(digits.length - scale).replace(/0+$/, '').padEnd(minScale, '0');
    return `${value < 0 ? '-' : ''}${digits.slice(0, digits.length - scale)}${fraction ? `.${fraction}` : ''}`;
}

/** 兩個十進位字串相乘，小數至少保留 minScale 位 */
function multiplyDecimal(a: string, b: string, minScale: number): string {
    const left = parseDecimal(a);
    const right = parseDecimal(b);
    return formatScaled(left.int * right.int, left.scale + right.scale, minScale);
}

/** 幣別小數位：玩家端沒有直接給，用餘額字串的位數推得，查不到就用 2 */
export function currencyScale(entry: SlotApiEntryResponse): number {
    return entry.player.balance ? parseDecimal(entry.player.balance).scale : 2;
}

/** 基本注：bet_size × bet_level × base_bet */
function baseBetAmount(size: string, level: number, baseBet: number, minScale: number): string {
    return multiplyDecimal(multiplyDecimal(size, String(level), 0), String(baseBet), minScale);
}

/**
 * 把 entry 的 Bet Size × Bet Level 攤平成現有 UI 的單一金額清單（暫時做法，正式版改成兩個選擇器）。
 * 由小到大排序；總額相同的只留第一個（size 較小的那組）。
 */
export function toBetPlan(entry: SlotApiEntryResponse): SlotBetOption[] {
    const plan = entry.game.limit_plan;
    const minScale = currencyScale(entry);
    const byAmount = new Map<string, SlotBetOption>();
    for (const size of plan.bet_sizes) {
        for (const level of plan.bet_levels) {
            const amount = baseBetAmount(size, level, plan.base_bet, minScale);
            if (!byAmount.has(amount)) byAmount.set(amount, { amount, size, level });
        }
    }
    return [...byAmount.values()].sort((a, b) => Number(a.amount) - Number(b.amount));
}

/** 進場資料轉成舊 UI 使用的 gameInitData（餘額、幣別、下注清單、預選下注額）。盤面仍用隨機初盤，之後再改用 last_step／default_board */
export function toLegacySlotInitDataFromEntry(entry: SlotApiEntryResponse, betPlan: readonly SlotBetOption[], layout: SlotGridLayout): any {
    const plan = entry.game.limit_plan;
    const minScale = currencyScale(entry);
    // 預選：上次的 size／level，沒有就用預設
    const size = entry.game.last_bet_size ?? plan.default_bet_size;
    const level = entry.game.last_bet_level ?? plan.default_bet_level;
    return {
        machine_info: {
            extra: {},
            bet_level: betPlan.map((option) => option.amount),
            last_bet: baseBetAmount(size, level, plan.base_bet, minScale),
            icon_indexes: Array.from({ length: layout.columns }, () => 2 + Math.floor(Math.random() * 20)),
            icon_table: [],
            spin_total_win: '0',
        },
        game: {
            balance: entry.player.balance,
            auth_key: '',
            currency: entry.player.currency,
        },
    };
}

// ===== 玩家端 API v5.1：一整局的步驟轉成演出用的 spin 資料 =====

/** 轉換時需要的下注與版面資訊 */
export interface SlotSpinContext {
    /** 基本注（bet_size × bet_level × base_bet），用來把事件裡的倍數換成顯示金額 */
    baseBet: string;
    /** 幣別小數位 */
    minScale: number;
    currency: string;
    /** 可視列數；盤面多出來的列是隱藏列（EoH 的 row 0） */
    visibleRows: number;
}

/** 事件 detail 是 `k=v` 空白分隔 */
function parseDetail(detail: string | undefined): Record<string, string> {
    const result: Record<string, string> = {};
    for (const pair of (detail ?? '').split(/\s+/)) {
        const index = pair.indexOf('=');
        if (index > 0) result[pair.slice(0, index)] = pair.slice(index + 1);
    }
    return result;
}

/** WAY_WIN 的 `cells=col:row,col:row` 轉成 [[col,row],…]，row 含隱藏列 */
function parseCells(cells: string | undefined): number[][] {
    return (cells ?? '')
        .split(',')
        .filter(Boolean)
        .map((cell) => cell.split(':').map(Number));
}

/** 一個 stage 轉成一個舊格式的 step：盤面、這一組盤面的中獎組與贏分 */
function toLegacyStep(stage: SlotApiResultStage, events: readonly SlotApiResultEvent[], context: SlotSpinContext): SlotApiStep {
    // 零值欄位會被省略：缺 column／row 視為 0
    const cells = stage.rows_per_column.map((rows) => new Array<number>(rows).fill(0));
    for (const cell of stage.cells) cells[cell.column ?? 0][cell.row ?? 0] = cell.symbol_id;

    const sequence = stage.sequence ?? 0;
    const awards: SlotApiAward[] = events
        .filter((event) => event.type === 'WAY_WIN' && (event.stage_ref ?? 0) === sequence)
        .map((event) => {
            const detail = parseDetail(event.detail);
            return {
                SymbolID: Number(detail.symbol),
                Count: Number(detail.count),
                Positions: parseCells(detail.cells),
                // 事件倍數是未縮放的底注倍數，只供顯示（文件：金額以 step_win 為準）
                Pay: multiplyDecimal(event.multiplier ?? '0', context.baseBet, context.minScale)
            };
        });

    return {
        Grid: { Cols: stage.columns, Rows: Math.max(...stage.rows_per_column), Cells: cells },
        Awards: awards,
        Win: multiplyDecimal(stage.win_multiplier ?? '0', context.baseBet, context.minScale)
    };
}

/** 一個 result 的所有 stage 轉成舊格式的 step 陣列（一個 stage 一個） */
function toLegacyStepsFromResult(result: SlotApiStepResult | null, context: SlotSpinContext): SlotApiStep[] {
    const events = result?.events ?? [];
    return (result?.stages ?? []).map((stage) => toLegacyStep(stage, events, context));
}

/** 一組步驟（主遊戲一轉，或免費遊戲一轉）轉成舊格式的 step 陣列 */
function toLegacySteps(steps: readonly SlotApiStepObject[], context: SlotSpinContext): SlotApiStep[] {
    return steps.flatMap((step) => toLegacyStepsFromResult(step.result, context));
}

/** 免費遊戲每一轉的倍數資訊：本輪倍數（MULTIPLIER_APPLIED）、跨輪累積值（acc_after）與這一轉的贏分 */
function toFreeMultipliers(rounds: readonly { events: readonly SlotApiResultEvent[]; win: string }[], startAccumulated = 0): SlotApiFreeMultiplier[] {
    let accumulated = startAccumulated;
    return rounds.map((round, index) => {
        const applied = round.events.find((event) => event.type === 'MULTIPLIER_APPLIED');
        const after = parseDetail(applied?.detail).acc_after;
        if (after !== undefined) accumulated = Number(after);
        return { round: index + 1, mult: Number(applied?.multiplier ?? 0), acc: accumulated, win: round.win };
    });
}

const JACKPOT_TIERS: readonly SlotApiJackpotTier[] = ['MINI', 'MINOR', 'MAJOR', 'GRAND'];

/**
 * 玩家端 API 一轉的步驟（開局步與其後的連消步），轉成演出現在使用的 spin 回應。免費遊戲每一轉在播放時才取，見 toLegacyFreeSpin。
 * - 主遊戲一轉＝開局步與其後的連消步（TUMBLE）；免費遊戲每一轉＝FREE_SPIN 步與其後的連消步（FREE_TUMBLE）。
 * - 倍數、免費遊戲觸發、Jackpot 取自事件（MULTIPLIER_APPLIED、FREE_GAME_ENTERED、JACKPOT_HIT）。
 * @throws 主遊戲沒有盤面（result 為 null 時前端不得自行產生盤面）
 */
export function toLegacySpinResponse(steps: readonly SlotApiStepObject[], context: SlotSpinContext): SlotApiSpinResponse {
    const isFree = (step: SlotApiStepObject): boolean => step.step_type === 'FREE_SPIN' || step.step_type === 'FREE_TUMBLE' || step.step_type === 'BONUS_PICK';
    const firstFree = steps.findIndex(isFree);
    const mainSteps = firstFree < 0 ? steps : steps.slice(0, firstFree);

    // 免費遊戲：每個 FREE_SPIN 步開一組，FREE_TUMBLE 併入目前這組
    const freeGroups: SlotApiStepObject[][] = [];
    for (const step of firstFree < 0 ? [] : steps.slice(firstFree)) {
        if (step.step_type !== 'FREE_TUMBLE' || freeGroups.length === 0) freeGroups.push([]);
        freeGroups[freeGroups.length - 1].push(step);
    }

    const main = toLegacySteps(mainSteps, context);
    if (main.length === 0) throw new Error('主遊戲步驟沒有盤面（result 為 null）');

    const eventsOf = (group: readonly SlotApiStepObject[]): SlotApiResultEvent[] => group.flatMap((step) => step.result?.events ?? []);
    const mainEvents = eventsOf(mainSteps);

    // 倍數球加總：主遊戲 `terminal_sum`，免費遊戲 `round_sum`／`acc_after`（跨輪累積）
    const multiplierEvent = mainEvents.find((event) => event.type === 'MULTIPLIER_APPLIED');
    const freeMultipliers = toFreeMultipliers(freeGroups.map((group) => ({ events: eventsOf(group), win: group[group.length - 1].spin_win })));

    // Jackpot：落點格在 overlays.jackpot，符號本身不動；舊演出用「換成 jackpot 符號」表現
    const bufferRows = Math.max(0, Math.max(...mainSteps.flatMap((step) => (step.result?.stages ?? []).map((stage) => Math.max(...stage.rows_per_column)))) - context.visibleRows);
    const terminalReplacements: SlotApiTerminalReplacement[] = mainSteps.flatMap((step) =>
        (step.result?.stages ?? []).flatMap((stage) =>
            stage.cells
                // 層級 "1"–"4" 才是命中；後端會對沒中的落點標 "0"，不能只看有沒有值
                .filter((cell) => Number(cell.overlays?.jackpot) > 0)
                .map((cell) => ({
                    reason: 'JACKPOT',
                    position: { col: cell.column ?? 0, row: (cell.row ?? 0) - bufferRows },
                    from_symbol_id: cell.symbol_id,
                    to_symbol_id: SYMBOL_IDS.jackpot
                }))
        )
    );
    const jackpotEvent = mainEvents.find((event) => event.type === 'JACKPOT_HIT');
    const jackpotTier = Number(parseDetail(jackpotEvent?.detail).tier ?? 0);
    const jackpot: SlotApiJackpotSpinResult = jackpotEvent
        ? {
              won: true,
              tier: JACKPOT_TIERS[jackpotTier - 1] ?? '',
              // 金額來源文件沒寫清楚：先以「該層底注倍數 × 基本注」顯示（見 docs/api-v5.1-遷移分析.md §11.6）
              payout: multiplyDecimal(jackpotEvent.multiplier ?? '0', context.baseBet, context.minScale),
              currency: context.currency
          }
        : { won: false, tier: '', payout: '0', currency: context.currency };

    const first = steps[0];
    const last = steps[steps.length - 1];
    // 這一轉結束後局還沒結束（next_step_type 非 null）而且沒有免費遊戲的步驟＝免費遊戲接著開始，每一轉播放時才向後端要
    const freePending = firstFree < 0 && last.next_step_type !== null;
    const freeTriggered = mainEvents.some((event) => event.type === 'FREE_GAME_ENTERED') || freeGroups.length > 0 || freePending;
    const capEvent = steps.flatMap((step) => step.result?.events ?? []).find((event) => event.type === 'CAP_APPLIED');

    return {
        bet_id: first.bet_id,
        operation_id: first.round_id,
        // 局結束那一步的 round_win＝實際派彩；balance 也只有這一步才是派彩後餘額
        total_win: last.round_win,
        raw_engine_win: last.round_win,
        engine_win: last.round_win,
        max_win: { applied: !!capEvent, multiplier: capEvent?.multiplier ?? '', cap_amount: '' },
        multiplier: Number(multiplierEvent?.multiplier ?? 0),
        free_game_triggered: freeTriggered,
        outcome: Number(last.round_win) > 0 ? 'won' : 'lost',
        balance_after: last.balance,
        free_round: false,
        charged_wager: first.bet_amount,
        round_result: {
            schema_version: 'slot.round_result.v1',
            Main: main,
            Free: freeGroups.map((group) => toLegacySteps(group, context)),
            TotalWin: last.round_win,
            RNGUsed: [],
            Multiplier: Number(multiplierEvent?.multiplier ?? 0),
            FreeGameTriggered: freeTriggered,
            JackpotTier: jackpotTier,
            JackpotCount: jackpotEvent ? Number(parseDetail(jackpotEvent.detail).count ?? 0) : 0,
            FreeMultipliers: freeMultipliers,
            presentation: {
                version: 'player-api.v5.1',
                coordinate_space: { origin: 'top_left', columns: main[0].Grid.Cols, rows: context.visibleRows },
                main: { transitions: [], terminal_replacements: terminalReplacements },
                free_rounds: []
            }
        },
        jackpot,
        ...(freePending ? { free_spins_total: last.fg_total || Number(parseDetail(mainEvents.find((event) => event.type === 'FREE_GAME_ENTERED')?.detail).rounds ?? 0) } : {})
    };
}

/** 免費遊戲一轉（FREE_SPIN 步與其後的 FREE_TUMBLE 步），播放時才向後端取得 */
export interface SlotFreeSpin {
    steps: SlotApiStep[];
    multiplier: SlotApiFreeMultiplier;
    /** 這一轉結束後剩餘／總轉數（再觸發會讓總數增加） */
    remain: number;
    total: number;
    /** 局是否結束（最後一步 next_step_type 為 null） */
    finished: boolean;
    /** 整局累計贏分與派彩後餘額；局結束那一步才是最終值 */
    totalWin: string;
    balance: string;
}

/**
 * 免費遊戲一轉的步驟轉成舊格式：每個 stage 一個 step，加上這一轉的倍數資訊。
 * @param accumulatedBefore 前面各轉累積的倍數（MULTIPLIER_APPLIED 的 acc_after）
 */
export function toLegacyFreeSpin(steps: readonly SlotApiStepObject[], context: SlotSpinContext, accumulatedBefore: number): SlotFreeSpin {
    const last = steps[steps.length - 1];
    const multiplier = toFreeMultipliers([{ events: steps.flatMap((step) => step.result?.events ?? []), win: last.spin_win }], accumulatedBefore)[0];
    return {
        steps: toLegacySteps(steps, context),
        multiplier,
        remain: last.fg_remain,
        total: last.fg_total,
        finished: last.next_step_type === null,
        totalWin: last.round_win,
        balance: last.balance
    };
}

// ===== 玩家端 API v5.1：獎池與注單轉成舊格式 =====

/** 兩個十進位字串相減（a − b），小數至少保留 minScale 位 */
function subtractDecimal(a: string, b: string, minScale: number): string {
    const left = parseDecimal(a);
    const right = parseDecimal(b);
    const scale = Math.max(left.scale, right.scale);
    return formatScaled(left.int * 10 ** (scale - left.scale) - right.int * 10 ** (scale - right.scale), scale, minScale);
}

/** 獎池水位：只取這款遊戲、玩家幣別的池，層級 1–4 對應 MINI／MINOR／MAJOR／GRAND；負值一律顯示 0 */
export function toLegacyJackpotSnapshot(response: SlotApiJackpotsResponse, gameCode: string, currency: string): SlotApiJackpotPoolSnapshot {
    return {
        game_code: gameCode,
        currency,
        pool_group_id: '',
        pools: response.pools
            .filter((pool) => pool.currency === currency && JACKPOT_TIERS[pool.tier - 1])
            .map((pool) => ({ tier: JACKPOT_TIERS[pool.tier - 1], amount: Number(pool.current_value) < 0 ? '0' : pool.current_value })),
        as_of_ms: Date.now()
    };
}

/** 注單母單轉成舊格式的一筆摘要；新列表沒有 balance_after，留空 */
function toLegacyHistoryItem(round: SlotApiHistoryRound): SlotApiBetHistoryItem {
    const scale = parseDecimal(round.bet_amount).scale;
    return {
        operation_id: round.round_id,
        game_code: round.game_id,
        currency: round.currency,
        bet_amount: round.bet_amount,
        win_amount: round.payout_amount,
        raw_engine_win: round.payout_amount,
        engine_win: round.payout_amount,
        profit: subtractDecimal(round.payout_amount, round.bet_amount, scale),
        balance_after: '',
        created_at_ms: round.settled_at_unix * 1000,
        buy_feature: round.feature_flags.includes('BUY_FEATURE'),
        is_free_round: false
    };
}

/** 注單列表（頁碼）轉成舊格式；沒有下一頁時 has_more 為 false */
export function toLegacyBetHistory(list: SlotApiHistoryListResponse): SlotApiBetHistoryResponse {
    const hasMore = list.page < list.total_pages;
    return {
        items: list.rounds.map(toLegacyHistoryItem),
        ...(hasMore ? { has_more: true, next_cursor: String(list.page + 1) } : {})
    };
}

/**
 * 單局重播轉成舊格式。一張細單＝一整轉，所以把每張細單當成「一步」，沿用即時下注同一套轉換
 * （開局細單 BASE_SPIN／BUY_FEATURE 是主遊戲，FREE_SPIN 細單依序是免費遊戲各轉）。
 * @param buyMultiple 買入倍率；買入局的注額是基本注 × 倍率，要換回基本注才能算各組的顯示金額
 */
export function toLegacyBetDetail(response: SlotApiHistoryRoundResponse, visibleRows: number, buyMultiple: number): SlotApiBetDetailResponse {
    const { round } = response;
    const scale = parseDecimal(round.bet_amount).scale;
    // 只供顯示的基本注：買入局把注額除回倍率
    const bought = round.feature_flags.includes('BUY_FEATURE') && buyMultiple > 0;
    const context: SlotSpinContext = {
        baseBet: bought ? (Number(round.bet_amount) / buyMultiple).toFixed(scale) : round.bet_amount,
        minScale: scale,
        currency: round.currency,
        visibleRows
    };
    const steps = [...response.details]
        .sort((a, b) => a.seq - b.seq)
        .map((detail): SlotApiStepObject => ({
            step_id: detail.detail_id,
            round_id: round.round_id,
            bet_id: '',
            detail_id: detail.detail_id,
            step_type: detail.detail_type,
            next_step_type: null,
            bet_size: '',
            bet_level: 0,
            bet_amount: detail.bet_amount,
            balance: '',
            step_win: detail.payout_amount,
            spin_win: detail.payout_amount,
            round_win: round.payout_amount,
            fg_remain: 0,
            fg_total: 0,
            fg_added: 0,
            result: detail.result
        }));
    const spin = toLegacySpinResponse(steps, context);
    return { engine_win: round.payout_amount, raw_engine_win: round.payout_amount, round_result: spin.round_result, summary: toLegacyHistoryItem(round) };
}
