import { _decorator, Label, Node, Quat, sp, Vec3 } from 'cc';
import { SymbolViewSpine } from './SymbolViewSpine';
import { SymbolExtras } from './SymbolState';
import { trySetAnimation } from '../../utils/SpineSafe';
import AppAudio from '../../audio/AppAudio';
import { EFFECTSMAP } from '../../audio/AudioConfig';
import { GameRoot } from '../../GameRoot';

const { ccclass, property } = _decorator;

/** symbol_up 的閃電從出手到打到盤面的時間，音效對這個點播 */
const FIRE_IMPACT_TIME_SEC = 0.25;

/** symbol_m 的 `mul` 動畫播到這一刻才換成新的 skin 與數字（企劃 §20/§17） */
const MUL_SWAP_AT_SEC = 0.2;

/** 一次性動畫的保底秒數：Cocos 對 loop=false 的 spine 不保證觸發 complete */
const ONCE_FALLBACK_SEC = 1.2;

/**
 * 倍率球的顯示層。
 *
 * **為什麼 40 個倍率球 id 只有一支 prefab**：`SlotGameDefinition` 裡倍率球是 id 11–30（不可升級）
 * 與 111–130（可升級）共 40 個，但美術只有一支 `symbol_m` spine，長相差異全靠 skin
 * `m{side}_{tier}`——而 `side` 還不在 id 裡（由欄位決定）。做成 40 支 prefab 等於 40 份幾乎一樣的
 * 資產，而且 side 讓「id → prefab」這個對應根本不成立。所以池只認一個共用的符號 id，真正的
 * 長相由 {@link applyExtras} 在租借後回填。
 *
 * 這一顆包掉舊 `NgSymbol` 裡所有倍率球相關的方法：skin、常駐數字、升級特效（`symbol_m_fx`）、
 * 落雷（`symbol_up`）。呼叫端只透過 {@link SymbolCell} 下指令，不再直接摸 spine。
 */
@ccclass('1001/SymbolViewMultiplier')
export class SymbolViewMultiplier extends SymbolViewSpine {
    @property({ type: Label, tooltip: '常駐顯示倍率值的文字，例如 50x' })
    public valueLabel: Label = null!;

    @property({ type: sp.Skeleton, tooltip: '升級特效 symbol_m_fx，疊在球上蓋住數字；動畫名 horus／anubis' })
    public fxSkeleton: sp.Skeleton = null!;

    @property({ type: sp.Skeleton, tooltip: '落雷 symbol_up，skin 依 side 選 horus／anubis' })
    public upSkeleton: sp.Skeleton = null!;

    /**
     * 每次租借／歸還都遞增，用來擋掉上一次演出留下的延遲回呼。
     *
     * 池化之後這件事比改版前更要緊：同一顆物件會被不同的格子輪流租用，一個 1.2 秒後才觸發的
     * `scheduleOnce` 很可能落在「已經換人用」的時間點上，沒有代數檢查就會把上一局的倍數寫進
     * 這一局的球裡。
     */
    private generation = 0;

    /** 目前這顆球的參數，播升級動畫換 skin 時要用到 side */
    private extras: SymbolExtras | null = null;

    // 已經被收集 數字隨特效飛走了 之後升級動畫晚到的回填也不能再顯示
    private collected = false;

    // 落雷節點在球底下的原本位置 播完照這個還原
    private upHome: { parent: Node; pos: Vec3; scale: Vec3; rot: Quat } | null = null;

    /**
     * 還沒結束的 {@link once} 收尾函式。
     *
     * 歸還時 `unscheduleAllCallbacks()` 會把保底計時器一起取消，少了這份清單，演到一半被收回去的
     * 那支動畫其 Promise 就永遠不 settle——`await` 它的流程會無聲吊死（entry
     * `docs/agent-pitfalls.md` 坑 #35）。歸還時一律把它們全部叫一次。
     */
    private readonly pendingFinishers = new Set<() => void>();

    /**
     * 回填球的參數：設 spine skin 與數字。
     *
     * @param extras 球的 side／tier／value；null 表示這一格不是球（理論上不會發生，防呆）。
     */
    public override applyExtras(extras: SymbolExtras | null): void {
        this.extras = extras;
        if (!extras) {
            if (this.valueLabel) this.valueLabel.node.active = false;
            return;
        }
        this.setBallSkin(extras.side, extras.tier);
        this.setBallValue(extras.value);
    }

    protected override onInit(): void {
        super.onInit();
        const up = this.upSkeleton;
        if (up?.node.parent) {
            this.upHome = { parent: up.node.parent, pos: up.node.position.clone(), scale: up.node.scale.clone(), rot: up.node.rotation.clone() };
        }
    }

    public override onRent(symbolId: number): void {
        this.generation++;
        this.collected = false;
        super.onRent(symbolId);
    }

    /** 打斷進行中的升級與落雷演出：停掉回呼與排程 把落雷節點搬回來 球本身不動 */
    public interrupt(): void {
        this.generation++;
        this.unscheduleAllCallbacks();
        for (const finish of Array.from(this.pendingFinishers)) finish();
        this.restoreUpParent();
        for (const skeleton of [this.fxSkeleton, this.upSkeleton]) {
            if (!skeleton?.isValid) continue;
            skeleton.setCompleteListener(null!);
            skeleton.clearTracks();
            skeleton.setToSetupPose();
            skeleton.timeScale = 1;
            skeleton.node.active = false;
        }
    }

    /** 歸還：打斷演出並清掉球的參數 */
    public override onReturn(): void {
        this.interrupt();
        this.extras = null;
        this.collected = false;
        if (this.valueLabel) this.valueLabel.node.active = false;
        super.onReturn();
    }

    /**
     * 球首次落定時的落雷演出（企劃 §19）：`symbol_up` 打下來，`symbol_m` 同時播一次 `begin`。
     *
     * 落雷要搬到場景層的 FX 節點再播——它的範圍比一格大，留在 reel 底下會被盤面的 Mask 裁掉。
     * 播完搬回原位，這顆物件才能正常歸還。
     *
     * @returns 落雷播完後 resolve。
     */
    public playUp(): Promise<void> {
        const side = this.extras?.side ?? 1;
        if (this.skeleton) trySetAnimation(this.skeleton, 'begin', false, 'SymbolViewMultiplier.playUp');

        const up = this.upSkeleton;
        if (!up?.isValid) return Promise.resolve();

        const generation = this.generation;
        up.node.active = true;
        try {
            up.setSkin(side === 2 ? 'anubis' : 'horus');
        } catch (err) {
            console.warn('[SymbolViewMultiplier] symbol_up 沒有對應的 skin，沿用預設', err);
        }

        const fxNode = GameRoot.getInstance()?.symbolFxNode;
        if (fxNode) up.node.setParent(fxNode, true);

        trySetAnimation(up, 'animation', false, 'SymbolViewMultiplier.playUp');
        this.scheduleOnce(() => AppAudio.getInstance().playEffect(EFFECTSMAP.FIRE_GET_2), FIRE_IMPACT_TIME_SEC);

        return this.once(up, generation, () => {
            up.node.active = false;
            this.restoreUpParent();
        });
    }

    /**
     * 升級演出（企劃 §20/§17）：`symbol_m` 播一次 `mul`，到 200ms 換成新的 skin 與數字，
     * 同時 `symbol_m_fx` 疊在球上播一次（side 1 = 荷魯斯 horus、2 = 阿努比斯 anubis）。
     *
     * @param side 角色側。
     * @param newTier 新的顏色階。
     * @param newValue 新的倍率值。
     * @returns 升級動畫播完後 resolve。
     */
    public playMul(side: number, newTier: number, newValue: number): Promise<void> {
        const generation = this.generation;

        if (this.fxSkeleton?.isValid) {
            this.fxSkeleton.node.active = true;
            trySetAnimation(this.fxSkeleton, side === 2 ? 'anubis' : 'horus', false, 'SymbolViewMultiplier.playMul(fx)');
            void this.once(this.fxSkeleton, generation, () => {
                if (this.fxSkeleton?.node?.isValid) this.fxSkeleton.node.active = false;
            });
        }

        if (!this.skeleton?.isValid) {
            this.applyExtras({ side, tier: newTier, value: newValue });
            return Promise.resolve();
        }

        trySetAnimation(this.skeleton, 'mul', false, 'SymbolViewMultiplier.playMul');
        this.scheduleOnce(() => {
            if (generation !== this.generation) return;
            this.applyExtras({ side, tier: newTier, value: newValue });
        }, MUL_SWAP_AT_SEC);

        return this.once(this.skeleton, generation);
    }

    /** 被收集：播一次 `collect`，跟收集軌跡的 spine 同步 */
    public playCollect(): void {
        // 數字跟著特效飛走 符號上的先消失
        this.collected = true;
        if (this.valueLabel) this.valueLabel.node.active = false;
        if (this.skeleton) trySetAnimation(this.skeleton, 'collect', false, 'SymbolViewMultiplier.playCollect');
    }

    /**
     * 設定球的 skin。
     *
     * @param side 角色側。
     * @param tier 顏色階。
     */
    private setBallSkin(side: number, tier: number): void {
        if (!this.skeleton?.isValid) return;
        try {
            this.skeleton.setSkin(`m${side}_${tier}`);
        } catch (err) {
            console.warn(`[SymbolViewMultiplier] symbol_m 沒有 skin m${side}_${tier}，沿用預設`, err);
        }
    }

    /**
     * 設定球上的倍率數字。
     *
     * @param value 倍率值；null 表示還不知道，這時不顯示數字。
     */
    private setBallValue(value: number | null): void {
        if (!this.valueLabel) return;
        if (value == null || this.collected) {
            this.valueLabel.node.active = false;
            return;
        }
        this.valueLabel.string = `${value}x`;
        this.valueLabel.node.active = true;
    }

    /** 把落雷節點搬回球底下並還原位置 沒搬走過也安全 */
    private restoreUpParent(): void {
        const up = this.upSkeleton;
        const home = this.upHome;
        if (!up?.node?.isValid || !home?.parent.isValid) return;
        if (up.node.parent !== home.parent) up.node.setParent(home.parent, false);
        up.node.setPosition(home.pos);
        up.node.setScale(home.scale);
        up.node.setRotation(home.rot);
    }

    /**
     * 等一支 spine 播完，帶保底計時器與代數檢查。
     *
     * 保底是必要的：Cocos 對 `loop = false` 的 spine 不保證觸發 complete，少了它這個 Promise
     * 會永遠不 settle，`await` 它的演出流程無聲吊死（entry `docs/agent-pitfalls.md` 坑 #35）。
     *
     * @param skeleton 要等的 spine。
     * @param generation 呼叫當下的代數；期間被歸還再租出去的話收尾就不做了。
     * @param onFinish 收尾動作，只在代數沒變時執行。
     * @returns 播完或保底時間到之後 resolve。
     */
    private once(skeleton: sp.Skeleton, generation: number, onFinish?: () => void): Promise<void> {
        return new Promise<void>((resolve) => {
            let done = false;
            const finish = (): void => {
                if (done) return;
                done = true;
                this.pendingFinishers.delete(finish);
                if (skeleton?.isValid) skeleton.setCompleteListener(null!);
                if (generation === this.generation) onFinish?.();
                resolve();
            };
            this.pendingFinishers.add(finish);
            skeleton.setCompleteListener((entry) => {
                if (entry.trackIndex === 0) finish();
            });
            this.scheduleOnce(finish, ONCE_FALLBACK_SEC);
        });
    }
}
