import { instantiate, Node, sp, tween, Tween, type TweenEasing, UITransform, Vec3 } from 'cc';
import { GameTask } from './GameTask';
import type { SlotApiTerminalReplacement } from '../net/SlotApiTypes';
import type { SlotAward, SlotRoundStep } from '../models/SlotRound';
import { WinFloatLabel } from '../reel/view/WinFloatLabel';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';
import AppAudio, { StagedEffectPlayer } from '../audio/AppAudio';
import { playLoopBySpeed } from '../audio/AudioBehaviorTypes';
import { EFFECTSMAP, REEL_STOP_BY_KIND, REEL_STOP_BY_SYMBOL_ID, REEL_STOP_NORMAL_POOL, REEL_STOP_NORMAL_PRIORITY, SPEED_BEHAVIOR, WIN_FX_STAGES } from '../audio/AudioConfig';
import GameConfigManager from '../config/GameConfigManager';
import { raceSkip, skipWait } from '../controllers/SkipWait';

interface IReelSpinStrategy<TGame, TInput> {
    run(game: TGame, input: TInput): Promise<number[][] | null>;
}

/**
 * 轉輪停止 + 消去落下迴圈的完整演出邏輯（原 GameMain_1001.playCascadeReels 及其專屬
 * 子邏輯 runTumbleSwap/applyMultiplierLabelsCol/applyMultiplierLabels/playCharacterMul/
 * playChaMul/spawnWinFloats/playWinFloat/pickCenterCell/shakeScreen，皆已確認只被
 * playCascadeReels 這條路徑呼叫，故整批搬進此檔案，從 GameMain_1001 移除）。
 *
 * 匯出成獨立函式（而非只包在 Task 內）是因為免費遊戲每一局
 * （PlayFreeRoundTask）也需要重跑同一套演出邏輯，兩處共用同一份實作。
 */
export async function runCascadeReels(game: ISlotGameMain<GameViewAdapter>, steps: readonly SlotRoundStep[], terminalReplacements?: SlotApiTerminalReplacement[]): Promise<number[][] | null> {
    const firstGrid = steps?.[0]?.grid;
    if (!firstGrid?.columns?.length) return null;
    const visibleRows = firstGrid.layout.visibleRows;

    let firstRedShaken = false;
    /** Scatter 發亮計數 前兩顆播 S1_GET_1 第三顆以上播 S1_GET_2 */
    let scattersRevealed = 0;
    // 中獎外框三階遞進音效
    const winFxStages = new StagedEffectPlayer(GameConfigManager.GAMEID, WIN_FX_STAGES);

    // 快停 轉動中再點一下 初始盤立刻落定直接進演出
    const quick = { on: false, releases: new Set<() => void>() };
    // 等指定秒數 快停時立刻結束
    const waitUnlessQuick = (seconds: number): Promise<void> => new Promise<void>((resolve) => {
        if (quick.on || seconds <= 0) {
            resolve();
            return;
        }
        const done = (): void => {
            quick.releases.delete(release);
            resolve();
        };
        const release = (): void => {
            game.unschedule(done);
            done();
        };
        quick.releases.add(release);
        game.scheduleOnce(done, seconds);
    });
    const onQuickStop = (): void => {
        if (quick.on) return;
        quick.on = true;
        for (const release of Array.from(quick.releases)) release();
        game.forEachView((v) => v.slotMachineView.reelViews.forEach((reel) => reel.quickStopTumble()));
    };

    const shakeScreen = (): void => {
        for (const view of game.allViews) {
            // 原本整個畫面一起搖
            // const node = view?.node;
            // 只搖輪帶框與輪帶
            for (const node of [view?.reelBg, view?.slotMachineView?.node]) {
                if (!node || !node.activeInHierarchy) continue;
                const base = node.getPosition();
                Tween.stopAllByTarget(node);
                const t = tween(node);
                const offs = [16, -12, 9, -6, 3];
                for (const dx of offs) t.to(0.045, { position: new Vec3(base.x + dx, base.y - dx * 0.35, base.z) });
                t.to(0.045, { position: new Vec3(base.x, base.y, base.z) }).start();
            }
        }
    };

    /** 單顆球落定套用 symbol_m 動畫球 + 數字 以及 scatter/jackpot 的 spine 揭露
     * 避免球/spine 先顯示靜態圖一段時間才變——轉動掉落途中 setSymbolDisplay 一律只顯示靜態圖
     * 落定後才由這裡呼叫 revealScatter/revealJackpot 打開 */
    const applyMultiplierLabelRow = (cols: number[][], sideByCol: number[], col: number, row: number, landed: boolean): void => {
        const reelsH = game.viewH.slotMachineView.reelViews;
        if (col >= cols.length || col >= reelsH.length) return;
        const side = sideByCol[col] ?? 1;
        const m = game.definition.symbols.resolve(cols[col][row]);
        const value = m.kind === 'multiplier' ? m.value : null;
        reelsH[col]?.setMultiplierLabel(row, value, side, m.colorTier);
        game.viewV?.slotMachineView.reelViews[col]?.setMultiplierLabel(row, value, side, m.colorTier);
        if (m.kind === 'scatter') {
            reelsH[col]?.revealScatter(row);
            game.viewV?.slotMachineView.reelViews[col]?.revealScatter(row);
            if (landed) {
                scattersRevealed++;
                AppAudio.getInstance().playEffect(
                    scattersRevealed <= 2 ? EFFECTSMAP.S1_GET_1 : EFFECTSMAP.S1_GET_2,
                    { interruptPaths: [EFFECTSMAP.S1_GET_1, EFFECTSMAP.S1_GET_2] }
                );
            }
        }
        if (m.kind === 'jackpot') {
            reelsH[col]?.revealJackpot(row);
            game.viewV?.slotMachineView.reelViews[col]?.revealJackpot(row);
        }
        if (m.kind === 'multiplier' && m.colorTier === 1 && !firstRedShaken) {
            firstRedShaken = true;
            shakeScreen();
        }
    };

    /** 整欄套用（安全網用，冪等）：實際顯示已經由每顆球自己落定時的 onRowSettled 觸發過一次，
     * 這裡不重複帶 landed=true，避免 scatter 音效被算兩次 */
    const applyMultiplierLabelsCol = (cols: number[][], sideByCol: number[], col: number, landedRows?: ReadonlySet<number>): void => {
        if (col >= cols.length) return;
        for (let row = 0; row < cols[col].length; row++) {
            applyMultiplierLabelRow(cols, sideByCol, col, row, landedRows?.has(row) ?? false);
        }
    };

    /** 依盤面 ids 驅動每顆倍率球的 symbol_m 動畫球(side/tier) + 常駐倍率數字，非倍率球清掉 */
    const applyMultiplierLabels = (cols: number[][], sideByCol: number[], landedRowsByCol?: ReadonlyMap<number, ReadonlySet<number>>): void => {
        const colCount = Math.min(cols.length, game.viewH.slotMachineView.reelViews.length);
        for (let col = 0; col < colCount; col++) {
            applyMultiplierLabelsCol(cols, sideByCol, col, landedRowsByCol?.get(col));
        }
    };

    /**
     * 播該欄的停輪音：由 tumbleFill／cascadeFill 在該欄最下面那顆到達 targetY 時觸發。
     *
     * @param ids 該欄這次落下的符號 id，用來挑 Scatter／Jackpot 的特殊停輪音。
     */
    const playReelStopSound = (ids: number[]): void => {
        const normalPath = REEL_STOP_NORMAL_POOL[Math.floor(Math.random() * REEL_STOP_NORMAL_POOL.length)];
        const candidates = new Map<string, { path: string; priority: number }>();
        candidates.set(normalPath, { path: normalPath, priority: REEL_STOP_NORMAL_PRIORITY });
        for (const id of ids ?? []) {
            const special = REEL_STOP_BY_SYMBOL_ID[id] ?? REEL_STOP_BY_KIND[game.definition.symbols.resolve(id).kind];
            if (!special) continue;
            const existing = candidates.get(special.path);
            if (!existing || special.priority > existing.priority) candidates.set(special.path, special);
        }
        const winner = Array.from(candidates.values()).reduce((current, candidate) => (candidate.priority > current.priority ? candidate : current));
        // 每欄落定都要播放 但 reel_stop_1/2 共用單聲道群組 先截斷上一個尾音避免疊加變大聲
        AppAudio.getInstance().playEffect(winner.path, { interruptPaths: REEL_STOP_NORMAL_POOL });
    };

    const playChaMul = (cha: Node | null): void => {
        const sk = cha?.getComponent(sp.Skeleton);
        if (!sk) return;
        AppAudio.getInstance().playEffect(EFFECTSMAP.FIRE_GET_1);
        sk.setAnimation(0, 'mul', false);
        sk.setCompleteListener(() => {
            sk.setCompleteListener(null!);
            sk.setAnimation(0, 'idle', true);
        });
    };

    /** 倍率球出現時對應角色舉手:symbol_m2→cha_001(荷魯斯)、symbol_m1→cha_002(阿努比斯),播完回 idle */
    const playCharacterMul = (horus: boolean, anubis: boolean): void => {
        game.forEachView((v) => {
            const root = v.bg?.parent;
            if (!root) return;
            if (horus) playChaMul(root.getChildByName('cha_001'));
            if (anubis) playChaMul(root.getChildByName('cha_002'));
        });
    };

    const runTumbleSwap = async (boardNamesByCol: string[][], onColFilled?: (col: number) => void): Promise<void> => {
        const timing = game.cascadeTiming();
        const colCount = boardNamesByCol.length;
        const promises: Promise<void>[] = [];
        for (let col = 0; col < colCount; col++) {
            const thisCol = col;
            const symbolNames = boardNamesByCol[col];
            promises.push(
                waitUnlessQuick((col * timing.colDelay) / 1000)
                    .then(() =>
                        Promise.all(
                            game.allViews.map((v) => {
                                const rv = v.slotMachineView.reelViews[thisCol];
                                return rv ? rv.tumbleClear(timing.tumbleClear, 0.04, timing.tumbleClearEase as TweenEasing) : Promise.resolve();
                            })
                        )
                    )
                    .then(() => {
                        // 該欄最下面那顆落到targetY就播停輪音 不等整欄；H/V 兩個 view 都會觸發 只播一次
                        let fired = false;
                        const onBottomLanded = () => {
                            if (fired) return;
                            fired = true;
                            playReelStopSound(currentCols[thisCol]);
                        };
                        // 每顆球自己落定(到達targetY)就套倍率球/scatter/jackpot,不用等整欄——
                        // H/V 兩個 view 各自的 tumbleFill 都會呼叫到同一個 row,用 Set 去重避免重複套用/scatter 音效算兩次
                        const settledRows = new Set<number>();
                        const onRowSettled = (row: number) => {
                            if (settledRows.has(row)) return;
                            settledRows.add(row);
                            applyMultiplierLabelRow(currentCols, sideByCol, thisCol, row, true);
                        };
                        return Promise.all(
                            game.allViews.map((v) => {
                                const rv = v.slotMachineView.reelViews[thisCol];
                                return rv
                                    ? rv.tumbleFill(symbolNames, timing.tumbleFill, 0.04, onBottomLanded, timing.tumbleFillEase as TweenEasing, onRowSettled)
                                    : Promise.resolve();
                            })
                        );
                    })
                    .then(() => {
                        if (onColFilled) onColFilled(thisCol);
                    })
            );
        }
        await Promise.all(promises);
    };

    // 跳過時一併清掉
    const winFloatNodes: Node[] = [];
    const playWinFloat = (parent: Node, pos: Vec3, win: number, _explodeTime: number): void => {
        const node = instantiate(game.winFloatLabel);
        winFloatNodes.push(node);
        parent.addChild(node);
        node.setPosition(pos);

        const wf = node.getComponent(WinFloatLabel);
        if (wf) {
            wf.play(win);
        } else {
            console.warn('[winFloat] prefab missing WinFloatLabel component');
            node.destroy();
        }
    };

    /** 方形中心最近的 cell（平手取左→上），避開跟 avoid 同列左右相鄰的格子（防數字重疊） */
    const pickCenterCell = (cells: { col: number; row: number }[], avoid: { col: number; row: number }[] = []): { col: number; row: number } => {
        const cols = cells.map((c) => c.col);
        const rows = cells.map((c) => c.row);
        const cx = (Math.min(...cols) + Math.max(...cols)) / 2;
        const cy = (Math.min(...rows) + Math.max(...rows)) / 2;
        const ranked = [...cells].sort((a, b) => {
            const da = (a.col - cx) ** 2 + (a.row - cy) ** 2;
            const db = (b.col - cx) ** 2 + (b.row - cy) ** 2;
            if (Math.abs(da - db) > 1e-6) return da - db;
            if (a.col !== b.col) return a.col - b.col;
            return a.row - b.row;
        });
        const clash = (c: { col: number; row: number }) => avoid.some((p) => p.row === c.row && Math.abs(p.col - c.col) <= 1);
        return ranked.find((c) => !clash(c)) ?? ranked[0];
    };

    /** 中獎群組原地飄分：每種消除 symbol 在其方形中心 cell 飄出該群贏分 */
    const spawnWinFloats = (awards: readonly SlotAward[], colElimRows: Record<number, number[]>, currentCols: number[][], explodeTime: number): void => {
        if (!game.winFloatLabel) return;

        const winBySymbol = new Map<number, number>();
        for (const a of awards ?? []) winBySymbol.set(a.symbolId, Number(a.pay) || 0);

        const cellsBySymbol: Record<number, { col: number; row: number }[]> = {};
        for (const colStr of Object.keys(colElimRows)) {
            const col = Number(colStr);
            for (const row of colElimRows[col]) {
                const sym = currentCols[col]?.[row];
                if (sym === undefined) continue;
                (cellsBySymbol[sym] ??= []).push({ col, row });
            }
        }

        const placed: { col: number; row: number }[] = [];
        for (const symStr of Object.keys(cellsBySymbol)) {
            const sym = Number(symStr);
            const win = winBySymbol.get(sym) ?? 0;
            if (win <= 0) continue;
            const center = pickCenterCell(cellsBySymbol[sym], placed);
            placed.push(center);
            const posIdx = center.row + 2;
            for (const v of game.allViews) {
                const rv = v.slotMachineView?.reelViews?.[center.col];
                const parent = v.slotMachineView?.node;
                if (!rv || !parent) continue;
                const worldPos = rv.getCellWorldPosition(posIdx);
                const localPos = parent.getComponent(UITransform)!.convertToNodeSpaceAR(worldPos);
                playWinFloat(parent, localPos, win, explodeTime);
            }
        }
    };

    /** 跳過：盤面與贏分欄直接設成最終結果 */
    const settleSkipped = (): void => {
        for (const node of winFloatNodes) if (node.isValid) node.destroy();
        winFloatNodes.length = 0;
        const finalCols = toMutableCols(steps[steps.length - 1].grid);
        for (let col = 0; col < colCount; col++) currentCols[col] = finalCols[col];
        game.allViews.forEach((v) => {
            for (let col = 0; col < colCount; col++) {
                v.slotMachineView.reelViews[col]?.snapToBoard(currentCols[col].map((id) => frameIdxByName(frameName(id, col))));
            }
        });
        applyMultiplierLabels(currentCols, sideByCol);
        const totalWin = steps.reduce((sum, st) => sum + (Number(st.win) || 0), 0);
        Tween.stopAllByTarget(game.winBarProxy);
        game.winBarValue = totalWin;
        game.winBarProxy.v = totalWin;
        game.setWinBarNum(totalWin);
    };

    const timing = game.cascadeTiming(); // 整局固定（spin 當下的檔位）

    const reelViews = game.viewH.slotMachineView.reelViews;
    const colCount = Math.min(firstGrid.columns.length, reelViews.length);

    // side（神）後端沒帶 → client per-ball 隨機，整局每欄固定（m1=荷魯斯 / m2=阿努比斯）
    const sideByCol: number[] = [];
    for (let c = 0; c < colCount; c++) sideByCol[c] = Math.random() < 0.5 ? 1 : 2;

    const frameName = (id: number, col: number): string => game.definition.symbols.frameName(id, sideByCol[col]);
    const frameIdxByName = (name: string): number => Math.max(0, reelViews[0].frameIdxByName(name));
    // Grid 已經由 SlotRoundMapper／SlotGridDecoder 解碼過（buffer 已移除），這裡只需要複製成可變動的工作副本
    const toMutableCols = (grid: SlotRoundStep['grid']): number[][] => grid.columns.map((column) => [...column.symbolIds]);

    const currentCols = toMutableCols(firstGrid);
    const boardNamesByCol: string[][] = [];
    for (let col = 0; col < colCount; col++) {
        const ids = currentCols[col];
        boardNamesByCol.push(ids.map((id) => frameName(id, col)));
    }

    // 倍率球出現 → 對應角色舉手(mul)，稍候盤面落定打雷（m1=荷魯斯 cha_001、m2=阿努比斯 cha_002）
    const colHasBall = (ids: number[]): boolean => ids.some((id) => game.definition.symbols.resolve(id).kind === 'multiplier');
    const hasHorusBall = currentCols.some((ids, col) => colHasBall(ids) && sideByCol[col] === 1);
    const hasAnubisBall = currentCols.some((ids, col) => colHasBall(ids) && sideByCol[col] === 2);
    // 落下階段開始才接受快停 結束一定要拿掉
    game.setQuickStopHandler(onQuickStop);
    try {
        if (hasHorusBall || hasAnubisBall) {
            playCharacterMul(hasHorusBall, hasAnubisBall);
            await waitUnlessQuick(game.charMulLeadMs / 1000);
        }

        // 輪軸開始轉動，查 SPEED_BEHAVIOR 表決定快停/極速模式要不要播（G6）
        playLoopBySpeed(SPEED_BEHAVIOR, EFFECTSMAP.REEL_START, game.storeManager.getGameStore().turboStatus);

        // 每顆球自己落定當下就套倍率球（tumbleFill 的 onRowSettled，不用等整欄）；
        // 這裡整欄再套一次只是安全網（冪等，不重複帶 landed 避免 scatter 音效算兩次）
        await runTumbleSwap(boardNamesByCol, (col) => {
            applyMultiplierLabelsCol(currentCols, sideByCol, col);
            // playReelStopSound(currentCols[col]); // 播該欄停輪音(這裡是全部動畫做完才播) 移到 tumbleFill
        });
    } finally {
        game.setQuickStopHandler(null);
        game.forEachView((v) => v.slotMachineView.reelViews.forEach((reel) => reel.resetQuickStopTumble()));
    }

    AppAudio.getInstance().stopLoopEffect(EFFECTSMAP.REEL_START);
    game.allViews.forEach((v) => v.slotMachineModel.onAllStopped());
    applyMultiplierLabels(currentCols, sideByCol);

    // 消除迴圈：跑 server 每個有中獎的 step（終盤段 awards=[] 自動跳過）
    for (let i = 0; i < steps.length; i++) {
        if (game.spinSkip.isSkipped) break;
        const awards = steps[i].awards.filter((a) => game.definition.symbols.resolve(a.symbolId).kind !== 'scatter');
        if (awards.length === 0) continue;

        if (await skipWait(game, timing.breath / 1000)) break;

        const elimSymbolIds = new Set<number>(awards.map((a) => a.symbolId));
        const nextGrid = steps[i + 1]?.grid;
        const nextCols = nextGrid ? toMutableCols(nextGrid) : null;

        const colElimRows: Record<number, number[]> = {};
        const toMapByCol: Record<number, number[]> = {};
        const newFillCountByCol: Record<number, number> = {};
        for (let col = 0; col < colCount; col++) {
            const elimRows: number[] = [];
            for (let row = 0; row < currentCols[col].length; row++) {
                if (elimSymbolIds.has(currentCols[col][row])) elimRows.push(row);
            }
            if (elimRows.length === 0) continue;
            colElimRows[col] = elimRows;
            // 倖存者用「當前盤的 id」保留身分（避免被 nextGrid 覆蓋成別的符號），
            // 新掉落從 nextGrid 該欄頂端取 elimCount 顆（新符號從上面進來）
            const survived = currentCols[col].filter((_, idx) => !elimRows.includes(idx));
            const newFills = nextCols?.[col].slice(0, elimRows.length) ?? [];
            newFillCountByCol[col] = newFills.length;
            toMapByCol[col] = [...newFills, ...survived].slice(0, visibleRows);
        }

        // 中獎符號爆炸前先播一次 symbol_win
        const winFxPromises: Promise<void>[] = [];
        for (const colStr of Object.keys(colElimRows)) {
            const col = Number(colStr);
            winFxPromises.push(reelViews[col].playWinFx(colElimRows[col], timing.winFx));
            game.viewV?.slotMachineView.reelViews[col]?.playWinFx(colElimRows[col], timing.winFx);
        }
        winFxStages.next();
        if (await raceSkip(game, Promise.all(winFxPromises))) break;

        // 爆炸 + 群中心飄分
        AppAudio.getInstance().playEffect(EFFECTSMAP.VANISH);
        const explodePromises: Promise<void>[] = [];
        for (const colStr of Object.keys(colElimRows)) {
            const col = Number(colStr);
            explodePromises.push(reelViews[col].explode(colElimRows[col], timing.explode));
            game.viewV?.slotMachineView.reelViews[col]?.explode(colElimRows[col], timing.explode);
        }
        spawnWinFloats(awards, colElimRows, currentCols, timing.float);
        // 用伺服器給的該步驟權威贏分 不要用 awards[].pay 自己加總 兩者可能因倍率等因素對不起來
        const stepWin = Number(steps[i].win) || 0;
        game.addWinBarScore(stepWin);
        if (await raceSkip(game, Promise.all(explodePromises))) break;
        if (await skipWait(game, timing.gap / 1000)) break;

        // 掉落
        // 音軌清單的 symbol_add：盤面補牌 共用 reel_stop_1/2
        // 該欄最下面那顆落到 targetY 就播停輪音；H/V 兩個 view 都會觸發 只播一次
        const fillPromises: Promise<void>[] = [];
        for (const colStr of Object.keys(colElimRows)) {
            const col = Number(colStr);
            const toMapFrames = toMapByCol[col].map((id) => frameIdxByName(frameName(id, col)));
            let fired = false;
            const onBottomLanded = () => {
                if (fired) return;
                fired = true;
                playReelStopSound(toMapByCol[col].slice(0, newFillCountByCol[col] ?? 0));
            };
            const fillDone = reelViews[col].cascadeFill(toMapFrames, colElimRows[col], timing.fill, timing.fillStagger, onBottomLanded, timing.fillEase as TweenEasing);
            game.viewV?.slotMachineView.reelViews[col]?.cascadeFill(toMapFrames, colElimRows[col], timing.fill, timing.fillStagger, onBottomLanded, timing.fillEase as TweenEasing);
            fillPromises.push(fillDone);
        }
        if (await raceSkip(game, Promise.all(fillPromises))) break;

        const newRowsByCol = new Map<number, ReadonlySet<number>>();
        for (const colStr of Object.keys(colElimRows)) {
            const col = Number(colStr);
            currentCols[col] = toMapByCol[col];
            const fillCount = newFillCountByCol[col] ?? 0;
            newRowsByCol.set(col, new Set(Array.from({ length: fillCount }, (_, row) => row)));
        }
        applyMultiplierLabels(currentCols, sideByCol, newRowsByCol); // 先套舊倍率值（升級格此刻顯示舊值）

        // 升級演出（企劃 §20/§17）：整盤只要有消除，所有倖存可升級球都升一階。
        // 落定後對全欄 row-by-row 比對 currentCols(舊) vs nextGrid(新)，變高者播 mul（內部 200ms 切新 tier/值），
        // 並把盤面補成新 id 供下一段 cascade 比對。
        if (nextCols) {
            for (let col = 0; col < colCount; col++) {
                const nextCol = nextCols[col];
                for (let row = 0; row < currentCols[col].length; row++) {
                    const oldM = game.definition.symbols.resolve(currentCols[col][row]);
                    const newM = game.definition.symbols.resolve(nextCol[row]);
                    if (oldM.kind === 'multiplier' && oldM.upgradeable && newM.kind === 'multiplier' && newM.value > oldM.value) {
                        reelViews[col]?.playMultiplierUpgrade(row, sideByCol[col], newM.colorTier, newM.value);
                        game.viewV?.slotMachineView.reelViews[col]?.playMultiplierUpgrade(row, sideByCol[col], newM.colorTier, newM.value);
                        currentCols[col][row] = nextCol[row];
                    }
                }
            }
        }
    }

    // 跳過
    if (game.spinSkip.isSkipped) settleSkipped();

    // JP symbol 由 presentation.main.terminal_replacements
    // 不能靠上面 Awards 迴圈帶出來
    const touchedJackpotCols = new Set<number>();
    for (const replacement of terminalReplacements ?? []) {
        const { col, row } = replacement.position;
        if (col < 0 || col >= colCount || row < 0 || row >= visibleRows) continue;
        if (currentCols[col][row] === replacement.to_symbol_id) continue;
        const frameIdx = frameIdxByName(frameName(replacement.to_symbol_id, col));
        const posIdx = row + 2;
        const symIdx = reelViews[col]?.findSymbolNodeAtPosIndex(posIdx) ?? -1;
        if (symIdx >= 0) reelViews[col].setSymbolDisplay(symIdx, frameIdx);
        const symIdxV = game.viewV?.slotMachineView.reelViews[col]?.findSymbolNodeAtPosIndex(posIdx) ?? -1;
        if (symIdxV >= 0) game.viewV!.slotMachineView.reelViews[col].setSymbolDisplay(symIdxV, frameIdx);
        currentCols[col][row] = replacement.to_symbol_id;
        touchedJackpotCols.add(col);
    }
    // 落定setSymbolDisplay只會顯示靜態圖
    // 動效判斷交給 applyMultiplierLabelsCol
    for (const col of touchedJackpotCols) applyMultiplierLabelsCol(currentCols, sideByCol, col);

    // viewV 的 cascade 是 fire-and-forget，把最終盤同步回去
    if (game.viewV) {
        for (let col = 0; col < colCount; col++) {
            const frameIdxes = currentCols[col].map((id) => frameIdxByName(frameName(id, col)));
            game.viewV.slotMachineView.reelViews[col]?.patchVisibleStrip(frameIdxes);
        }
    }

    return currentCols;
}

/**
 * 目前唯一的轉輪消去落下策略：直接委派給 runCascadeReels（tumble/cascade 玩法本體，
 * 含物理式掉落，見 ReelView.physicsFallDuration/appendLandingBounce）。
 * 實作 IReelSpinStrategy 只是把既有邏輯包成可替換的策略物件，行為與搬移前完全一致；
 * 未來新遊戲若要換一套轉輪演出（含一般不消去的 SimpleSpin 玩法），改成 new 一個別的
 * IReelSpinStrategy<ISlotGameMain<GameViewAdapter>> 實作即可，
 * 不需要動 CascadeReelsTask 本身。
 */
export interface TumbleCascadeInput {
    steps: readonly SlotRoundStep[];
    terminalReplacements?: SlotApiTerminalReplacement[];
}

export class TumbleCascadeStrategy implements IReelSpinStrategy<ISlotGameMain<GameViewAdapter>, TumbleCascadeInput> {
    public run(game: ISlotGameMain<GameViewAdapter>, input: TumbleCascadeInput): Promise<number[][] | null> {
        return runCascadeReels(game, input.steps, input.terminalReplacements);
    }
}

/** 對應 SGTask_NGSpin：轉輪停止 + 消去落下迴圈。addTask() 到頂層佇列時用這個薄殼。 */
export class CascadeReelsTask extends GameTask {
    constructor(
        private readonly game: ISlotGameMain<GameViewAdapter>,
        private readonly steps: readonly SlotRoundStep[],
        private readonly onResult: (cols: number[][] | null) => void,
        private readonly terminalReplacements?: SlotApiTerminalReplacement[],
        private readonly strategy: IReelSpinStrategy<ISlotGameMain<GameViewAdapter>, TumbleCascadeInput> = new TumbleCascadeStrategy()
    ) {
        super();
    }

    protected onStart(): void {
        this.strategy
            .run(this.game, { steps: this.steps, terminalReplacements: this.terminalReplacements })
            .then((cols) => this.onResult(cols))
            .catch((error) => console.warn('[CascadeReelsTask] failed', error))
            .finally(() => this.finish());
    }
}
